import{_ as i,o as n,c as k,a2 as u}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Sheria ya Kazi ya Usawa","description":"","frontmatter":{},"headers":[],"relativePath":"sw/41-共生劳动法.md","filePath":"sw/41-共生劳动法.md"}'),t={name:"sw/41-共生劳动法.md"};function o(e,a,h,w,z,l){return n(),k("div",null,[...a[0]||(a[0]=[u('<h1 id="sheria-ya-kazi-ya-usawa" tabindex="-1">Sheria ya Kazi ya Usawa <a class="header-anchor" href="#sheria-ya-kazi-ya-usawa" aria-label="Permalink to &quot;Sheria ya Kazi ya Usawa&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>41</td></tr><tr><td>Moduli</td><td>Mfumo wa Kisheria na Muundo wa Usimamizi</td></tr><tr><td>Maneno muhimu ya msingi</td><td>Kazi ya Usawa, Kazi Nyingi Faida Nyingi, Haki za Kazi, Mkataba wa Uzalishaji wa Pamoja, Kupinga Unyonyaji</td></tr></tbody></table><h2 id="_1-lengo-la-kisheria-na-kanuni-za-msingi" tabindex="-1">1. Lengo la Kisheria na Kanuni za Msingi <a class="header-anchor" href="#_1-lengo-la-kisheria-na-kanuni-za-msingi" aria-label="Permalink to &quot;1. Lengo la Kisheria na Kanuni za Msingi&quot;">​</a></h2><p>《Sheria ya Kazi ya Usawa》 ni moja ya sheria za msingi katika mfumo wa kisheria wa ustaarabu wa usawa wa nanga, sawa na 《Katiba ya Usawa》, na lengo lake ni kurekebisha shughuli zote za kazi na mchango ndani ya Hengyuanzhou, kuanzisha utaratibu wa usambazaji wa &quot;kazi nyingi faida nyingi, kukua kwa uhuru&quot;, na kutekeleza juu ya misingi ya sheria misingi ya unyonyaji wa mauaji.</p><p>Sheria hii inaweka kanuni zifuatazo za msingi:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th></tr></thead><tbody><tr><td>Kanuni ya Heshima ya Kazi</td><td>Kazi zote za kisheria zinalindwa na sheria, heshima ya mtu ya mfanyakazi haiwezi kuvunjwa</td></tr><tr><td>Kanuni ya Kazi Nyingi Faida Nyingi</td><td>Malipo ya kazi yanahusishwa moja kwa moja na kiwango cha mchango, kadiri mchango unavyoongezeka ndivyo faida inavyongezeka, kupata faida bila kazi kunakatazwa</td></tr><tr><td>Kanuni ya Kazi ya Hiari</td><td>Kazi ya kulazimisha na utumwa kunakatazwa, mfanyakazi ana haki ya kuchagua kwa uhuru maudhui ya kazi na njia ya kazi</td></tr><tr><td>Kanuni ya Malipo ya Haki</td><td>Malipo sawa kwa kazi sawa, ubaguzi wa malipo kulingana na kabila, kiwango cha mazoezi, asili unakatazwa</td></tr><tr><td>Kanuni ya Uhakikisho wa Kazi</td><td>Serikali na ustaarabu wana jukumu la kutoa mfanyakazi mazingira ya kazi salama na uhakikisho wa msingi wa jamii</td></tr><tr><td>Kanuni ya Ushirikiano wa Usawa</td><td>Kuchochea ushirikiano na msaada wa kina kati ya wafanyakazi, kupinga ushindani mbaya na mchezo wa zero-sum</td></tr></tbody></table><h2 id="_2-haki-za-msingi-za-wafanyakazi" tabindex="-1">2. Haki za Msingi za Wafanyakazi <a class="header-anchor" href="#_2-haki-za-msingi-za-wafanyakazi" aria-label="Permalink to &quot;2. Haki za Msingi za Wafanyakazi&quot;">​</a></h2><p>Sheria ya Kazi ya Usawa inatoa kila kiumbe chenye uwezo wa kazi ndani ya Hengyuanzhou haki zifuatazo:</p><ol><li><strong>Haki ya Ajira ya Usawa</strong>: Hakuna kiumbe kinachobaguliwa kwa kabila, kiwango cha mazoezi, asili, jinsia, n.k. katika mchakato wa kutafuta ajira na kuajiriwa.</li><li><strong>Haki ya Kuchagua Kazi kwa Uhuru</strong>: Mfanyakazi ana haki ya kuchagua ufundi, nafasi, na mahali pa kazi kulingana na mapenzi na uwezo wake mwenyewe, na ana haki ya kubadilisha ufundi kulingana na sheria.</li><li><strong>Haki ya Malipo ya Kustahiki</strong>: Mfanyakazi ana haki ya kupata malipo yanayolingana na mchango wake wa kazi, malipo hayafai kuwa chini ya kiwango cha chini cha uhakikisho kilichowekwa na ustaarabu.</li><li><strong>Haki ya Pumziko na Likizo</strong>: Mfanyakazi ana haki ya kupata mpangilio wa muda wa kazi unaofaa na likizo za mara kwa mara, kurefusha muda wa kazi bila kikomo kunakatazwa.</li><li><strong>Haki ya Usalama wa Kazi</strong>: Mfanyakazi ana haki ya kufanya kazi katika mazingira salama na yenye usafi, mwajiri lazima atoe hali za ulinzi wa kazi zinazofuata viwango.</li><li><strong>Haki ya Mafunzo ya Kitaaluma</strong>: Mfanyakazi ana haki ya kupata mafunzo ya ujuzi wa kitaaluma na mwongozo wa mazoezi, mwajiri na serikali wana jukumu la kutoa rasilimali za mafunzo.</li><li><strong>Haki ya Kuunda Shirika na Mazungumzo</strong>: Mfanyakazi ana haki ya kuunda au kujiunga na chama cha wafanyakazi kulingana na sheria, na ana haki ya kulinda haki zake kupitia mazungumzo ya pamoja.</li><li><strong>Haki ya Malalamiko na Ukombozi</strong>: Mfanyakazi, wakati haki zake za kazi zikitapakaa, ana haki ya kuwasilisha malalamiko na mashtaka kwa chuo cha arbitri la kazi na Korti ya Usawa.</li></ol><h2 id="_3-kisheria-kwa-mfumo-wa-mkataba-wa-uzalishaji-wa-pamoja" tabindex="-1">3. Kisheria kwa Mfumo wa Mkataba wa Uzalishaji wa Pamoja <a class="header-anchor" href="#_3-kisheria-kwa-mfumo-wa-mkataba-wa-uzalishaji-wa-pamoja" aria-label="Permalink to &quot;3. Kisheria kwa Mfumo wa Mkataba wa Uzalishaji wa Pamoja&quot;">​</a></h2><p>Mfumo wa mkataba wa uzalishaji wa pamoja ni mfumo wa msingi wa usambazaji wa rasilimali wa ustaarabu wa usawa wa nanga, na 《Sheria ya Kazi ya Usawa》 inaiweka katika fomu ya kisheria:</p><ul><li><strong>Mada ya Mkataba</strong>: Kila kiumbe chenye uwezo wa kazi kinaweza kuwa mada ya mkataba, mtu binafsi au jumuiya zote zinaweza kutia mkataba.</li><li><strong>Maudhui ya Mkataba</strong>: Inajumuisha lakini haiwi huku maendeleo ya rasilimali za mazoezi, matengenezo ya viwango, urithi wa maarifa, utafiti na maendeleo ya teknolojia, huduma za umma, n.k.</li><li><strong>Muda wa Mkataba</strong>: Unaamuliwa kulingana na asili ya maudhui ya mkataba, mikataba ya muda mfupi ni miaka 1 hadi 3, mikataba ya muda mrefu ni miaka 5 hadi 20, inaweza kufanywa upya baada ya kumalizika.</li><li><strong>Usambazaji wa Faida</strong>: Faida ya mkataba-wanaji inahusishwa moja kwa moja na uzalishaji wake, sehemu ya uzalishaji inapelekwa kwa akiba ya umma, sehemu iliyobaki ni mali ya mkataba-wanaji.</li><li><strong>Mfumo wa Kutoka</strong>: Mkataba-wanaji ana haki ya kutoka kwenye mkataba baada ya taarifa kabla ya muda wa kufaa, hanaweza kulazimishwa kubaki katika uhusiano wa mkataba.</li><li><strong>Kutatua Mizozo</strong>: Mizozo ya mkataba inatuliwa kwa kipaumbele kupitia arbitri ya kazi, yule ambaye hakuridhiki na matokeo ya arbitri anaweza kushtaki Korti ya Usawa.</li></ul><h2 id="_4-ulinzi-wa-maalum-wa-kazi" tabindex="-1">4. Ulinzi wa Maalum wa Kazi <a class="header-anchor" href="#_4-ulinzi-wa-maalum-wa-kazi" aria-label="Permalink to &quot;4. Ulinzi wa Maalum wa Kazi&quot;">​</a></h2><p>Kwa kujibu mahitaji maalum ya aina tofauti za uhai ndani ya Hengyuanzhou, sheria hii inaweka mfumo wa ulinzi wa maalum wa kazi:</p><table tabindex="0"><thead><tr><th>Kikundi Kilindalo</th><th>Hatua za Ulinzi wa Maalum</th></tr></thead><tbody><tr><td>Wanaofanya Mazoezi wa Awali</td><td>Hawafai kupewa kazi za hatari zaidi ya uwezo wao, lazima wapewe mwongozo wa mwalimu</td></tr><tr><td>Viumbe vya Kike katika Muda wa Ujauzito na Kuzalisha</td><td>Vina haki ya likizo ya uzazi yenye malipo isiyopungua miezi sita, hawafai kupewa kazi ya nguvu juu wakati wa kunyonyesha</td></tr><tr><td>Viumbe Vilemavu na Viliwanywa/Mgonjwa</td><td>Vina haki ya marekebisho ya nafasi ya kazi ya kufaa na uhakikisho wa mazingira ya kazi isiyo na vikwazo</td></tr><tr><td>Wafanyakazi wa Kabila Nyingine</td><td>Mwajiri lazima aheshimu tabia za mwili na desturi za kitamaduni za kabila nyingine, na kutoa hali za kazi zinazofaa</td></tr><tr><td>Wafanyakazi Wazee</td><td>Baada ya kufikia umri fulani, wanaweza kuomba kupunguza nguvu ya kazi au kuhamishwa kwa nafasi ya ushauri</td></tr></tbody></table><h2 id="_5-wajibu-wa-kisheria-na-uhakikisho-wa-utekelezaji" tabindex="-1">5. Wajibu wa Kisheria na Uhakikisho wa Utekelezaji <a class="header-anchor" href="#_5-wajibu-wa-kisheria-na-uhakikisho-wa-utekelezaji" aria-label="Permalink to &quot;5. Wajibu wa Kisheria na Uhakikisho wa Utekelezaji&quot;">​</a></h2><p>Mwajiri anayevunja masharti ya sheria hii atabeba wajibu ufuatao kulingana na ukubwa wa makosa:</p><ol><li>Kulipa malipo yanayostahiki kwa mfanyakazi na fidia (fidia ni mara 1 hadi 3 ya malilio yasiyolipwa).</li><li>Kuamriwa kurekebisha ndani ya muda, kukosa kurekebisha ndani ya muda kunapewa faini.</li><li>Katika visa vizito, leseni ya biashara itakatiwa na watu wanaohusika wanaotakiwa wajibu watazwa kushiriki katika kazi ya usimamizi kwa muda fulani.</li><li>Ikiwa inatokea makosa ya jinai, itafuatiliwa kwa wajibu wa jinai kulingana na sheria.</li></ol><p>Serikali inaweka chuo cha uangalizi wa kazi, kinachowajibika kwa uangalizi na ukaguzi wa utekelezaji wa sheria ya kazi kwa wajiri. Chama cha wafanyakazi kina haki ya kushiriki katika uangalizi wa kazi na mazungumzo ya pamoja kwa niaba ya wafanyakazi.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>《Sheria ya Kazi ya Usawa》 ni chombo cha kisheria cha dhana ya &quot;kazi nyingi faida nyingi&quot; ya ustaarabu wa usawa wa nanga. Imebadilisha kazi kutoka kuwa kipokezi cha unyonyaji kuwa haki inayoheshimiwa, na usambazaji kutoka kwa utekaji wa mauaji kuwa malipo yanayotegemea mchango, na kuweka msingi thabiti wa mfumo wa kazi kwa maendeleo ya pamoja ya kila kabila.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Kanuni za Msingi za Katiba ya Usawa)</li><li>06-多劳多得分配原理 (Kanuni ya Usambazaji wa Kazi Nyingi Faida Nyingi)</li><li>22-资源分配联产承包机制 (Mfumo wa Mkataba wa Uzalishaji wa Pamoja wa Usambazaji wa Rasilimali)</li><li>42-消费者保护法 (Sheria ya Ulinzi wa Watumiaji)</li></ul>',23)])])}const r=i(t,[["render",o]]);export{s as __pageData,r as default};
